                temp_t /= p;
            }
        }
        if (temp_t > 1) return "-1";

        auto get_min_digits = [&](const std::vector<int>& counts) {
            std::vector<int> res(10, 0);
            int twos = counts[2], threes = counts[3];
            res[5] = counts[5];
            res[7] = counts[7];

            res[9] = threes / 2;
            threes %= 2;
            res[8] = twos / 3;
            twos %= 3;

            if (threes > 0 && twos > 0) {
                res[6] = 1;
                threes--;
                twos--;
            } else if (threes > 0 && res[8] > 0) {
                res[8]--;
                res[9]++;
                res[6] = 2;
                threes--;
            }
            res[4] = twos / 2;
            twos %= 2;
            res[2] = twos;
            res[3] = threes;
            if (res[2] > 0 && res[6] > 0) {
                res[6]--;
                res[8]++;
                res[2]--;
            }
            return res;
        };

        auto build_suffix = [&](const std::vector<int>& counts, int length) {
            auto digits_map = get_min_digits(counts);
            std::string digs = "";
            for (int d = 2; d <= 9; ++d) {
                digs.append(digits_map[d], '0' + d);
            }
            std::string ans = std::string(length - digs.size(), '1') + digs;
            return ans;
        };

        std::vector<std::vector<int>> digit_factors(10, std::vector<int>(10, 0));
        digit_factors[2][2] = 1;
        digit_factors[3][3] = 1;
        digit_factors[4][2] = 2;
        digit_factors[5][5] = 1;
        digit_factors[6][2] = 1; digit_factors[6][3] = 1;
        digit_factors[7][7] = 1;
        digit_factors[8][2] = 3;
        digit_factors[9][3] = 2;

        int first_zero = num.find('0');
        if (first_zero == std::string::npos) {
            std::vector<int> num_p(10, 0);
            for (char ch : num) {
                for (int p : primes) num_p[p] += digit_factors[ch - '0'][p];
            }
            bool ok = true;
            for (int p : primes) if (num_p[p] < target_p[p]) ok = false;
            if (ok) return num;
        }

        int n = num.size();
        std::vector<int> prefix_p(10, 0);
        for (int i = 0; i < n; ++i) {
            int d = num[i] - '0';
            if (d == 0) break;
            for (int p : primes) prefix_p[p] += digit_factors[d][p];
        }

        int limit = (first_zero == std::string::npos) ? n : first_zero;
        for (int i = limit; i >= 0; --i) {
            int d_orig = 0;
            if (i < n) {
                d_orig = num[i] - '0';
                for (int p : primes) prefix_p[p] -= digit_factors[d_orig][p];
            }
            int spaces = n - 1 - i;
            int start_d = (i < n) ? (d_orig + 1) : 1;
            for (int bigger = start_d; bigger <= 9; ++bigger) {
                std::vector<int> needed(10, 0);
                for (int p : primes) {
                    int req = target_p[p] - prefix_p[p] - digit_factors[bigger][p];
                    if (req > 0) needed[p] = req;
                }
                auto min_digs = get_min_digits(needed);
                int sum_digs = 0;
                for (int d = 2; d <= 9; ++d) sum_digs += min_digs[d];
                if (sum_digs <= spaces) {
                    std::string pref = num.substr(0, i) + std::to_string(bigger);
                    std::string suff = build_suffix(needed, spaces);
                    return pref + suff;
                }
            }
        }

        std::vector<int> needed_all(10, 0);
        for (int p : primes) needed_all[p] = target_p[p];
        return build_suffix(needed_all, n + 1);
    }
