import java.util.*;

class Solution {
    public String smallestNumber(String num, long t) {
        int[] targetP = new int[10];
        long tempT = t;
        int[] primes = {2, 3, 5, 7};
        for (int p : primes) {
            while (tempT % p == 0) {
                targetP[p]++;
                tempT /= p;
            }
        }
        if (tempT > 1) return "-1";

        int[][] digitFactors = new int[10][10];
        digitFactors[2][2] = 1;
        digitFactors[3][3] = 1;
        digitFactors[4][2] = 2;
        digitFactors[5][5] = 1;
        digitFactors[6][2] = 1; digitFactors[6][3] = 1;
        digitFactors[7][7] = 1;
        digitFactors[8][2] = 3;
        digitFactors[9][3] = 2;

        int firstZero = num.indexOf('0');
        if (firstZero == -1) {
            int[] numP = new int[10];
            for (char ch : num.toCharArray()) {
                for (int p : primes) numP[p] += digitFactors[ch - '0'][p];
            }
            boolean ok = true;
            for (int p : primes) if (numP[p] < targetP[p]) ok = false;
            if (ok) return num;
        }

        int n = num.length();
        int[] prefixP = new int[10];
        for (int i = 0; i < n; i++) {
            int d = num.charAt(i) - '0';
            if (d == 0) break;
            for (int p : primes) prefixP[p] += digitFactors[d][p];
        }

        int limit = (firstZero == -1) ? n : firstZero;
        for (int i = limit; i >= 0; i--) {
            int dOrig = 0;
            if (i < n) {
                dOrig = num.charAt(i) - '0';
                for (int p : primes) prefixP[p] -= digitFactors[dOrig][p];
            }
            int spaces = n - 1 - i;
            int startD = (i < n) ? (dOrig + 1) : 1;
            for (int bigger = startD; bigger <= 9; bigger++) {
                int[] needed = new int[10];
                for (int p : primes) {
                    int req = targetP[p] - prefixP[p] - digitFactors[bigger][p];
                    if (req > 0) needed[p] = req;
                }
                int[] minDigs = getMinDigits(needed);
                int sumDigs = 0;
                for (int d = 2; d <= 9; d++) sumDigs += minDigs[d];
                if (sumDigs <= spaces) {
                    String pref = num.substring(0, i) + bigger;
                    String suff = buildSuffix(needed, spaces);
                    return pref + suff;
                }
            }
        }

        int[] neededAll = new int[10];
        for (int p : primes) neededAll[p] = targetP[p];
        return buildSuffix(neededAll, n + 1);
    }

    private int[] getMinDigits(int[] counts) {
        int[] res = new int[10];
        int twos = counts[2], threes = counts[3];
        res[5] = counts[5];
        res[7] = counts[7];
        res[9] = threes / 2;
        threes %= 2;
        res[8] = twos / 3;
        twos %= 3;
        if (threes > 0 && twos > 0) {
            res[6] = 1;
            threes--;
            twos--;
        } else if (threes > 0 && res[8] > 0) {
            res[8]--;
            res[9]++;
            res[6] = 2;
            threes--;
        }
        res[4] = twos / 2;
        twos %= 2;
        res[2] = twos;
        res[3] = threes;
        if (res[2] > 0 && res[6] > 0) {
            res[6]--;
            res[8]++;
            res[2]--;
        }
        return res;
    }

    private String buildSuffix(int[] counts, int length) {
        int[] digitsMap = getMinDigits(counts);
        StringBuilder sb = new StringBuilder();
        for (int d = 2; d <= 9; d++) {
            for (int c = 0; c < digitsMap[d]; c++) sb.append(d);
        }
        StringBuilder ans = new StringBuilder();
        int ones = length - sb.length();
        for (int i = 0; i < ones; i++) ans.append('1');
        ans.append(sb);
        return ans.toString();
    }
}

var smallestNumber = function(num, t) {
    t = BigInt(t);
    const primes = [2n, 3n, 5n, 7n];
    const targetP = { 2: 0, 3: 0, 5: 0, 7: 0 };
    let tempT = t;
    for (const p of primes) {
        const key = Number(p);
        while (tempT % p === 0n) {
            targetP[key]++;
            tempT /= p;
        }
