        res[3] = threes;
        if (res[2] > 0 && res[6] > 0) {
            res[6]--;
            res[8]++;
            res[2]--;
        }
        return res;
    }

    function buildSuffix(counts, length) {
        const digitsMap = getMinDigits(counts);
        let digs = "";
        for (let d = 2; d <= 9; d++) {
            digs += String(d).repeat(digitsMap[d]);
        }
        return "1".repeat(length - digs.length) + digs;
    }

    const digitFactors = {
        0: {}, 1: {},
        2: { 2: 1 }, 3: { 3: 1 },
        4: { 2: 2 }, 5: { 5: 1 },
        6: { 2: 1, 3: 1 }, 7: { 7: 1 },
        8: { 2: 3 }, 9: { 3: 2 }
    };

    const firstZero = num.indexOf('0');
    if (firstZero === -1) {
        const numP = { 2: 0, 3: 0, 5: 0, 7: 0 };
        for (let i = 0; i < num.length; i++) {
            const factors = digitFactors[Number(num[i])];
            for (const p in factors) numP[p] += factors[p];
        }
        let ok = true;
        for (const p of [2, 3, 5, 7]) {
            if (numP[p] < targetP[p]) ok = false;
        }
        if (ok) return num;
    }

    const n = num.length;
    const prefixP = { 2: 0, 3: 0, 5: 0, 7: 0 };
    for (let i = 0; i < n; i++) {
        const d = Number(num[i]);
        if (d === 0) break;
        const factors = digitFactors[d];
        for (const p in factors) prefixP[p] += factors[p];
    }

    const limit = (firstZero === -1) ? n : firstZero;
    for (let i = limit; i >= 0; i--) {
        let dOrig = 0;
        if (i < n) {
            dOrig = Number(num[i]);
            const factors = digitFactors[dOrig];
            for (const p in factors) prefixP[p] -= factors[p];
        }
        const spaces = n - 1 - i;
        const startD = (i < n) ? (dOrig + 1) : 1;
        for (let bigger = startD; bigger <= 9; bigger++) {
            const needed = { 2: 0, 3: 0, 5: 0, 7: 0 };
            const bFactors = digitFactors[bigger];
            for (const p of [2, 3, 5, 7]) {
                const req = targetP[p] - prefixP[p] - (bFactors[p] || 0);
                if (req > 0) needed[p] = req;
            }
            const minDigs = getMinDigits(needed);
            let sumDigs = 0;
            for (let d = 2; d <= 9; d++) sumDigs += minDigs[d];
            if (sumDigs <= spaces) {
                const pref = num.substring(0, i) + bigger;
                const suff = buildSuffix(needed, spaces);
                return pref + suff;
            }
